 if matched!=11 or conflicts!=[('603869','2026-07-03','price_basis_conflict')]:raise ValueError('twentysixth quote verification scope changed')
 audit.update(source_refs=[{k:v for k,v in s.items()if k!='text'}for s in sources],stock_reviews=reviews,stock_endpoint_points=matched,stock_return_windows=6,review_note='12端点11匹配；智知期初复权冲突，相关两段收益保持空值。',boundary='保持1e-9阈值；仅同期描述，不识别公告净影响。')
